export const OCC_INTEGRATIONS=[
  {id:'native',label:'Native application only',description:'The native application receives the selected point. No common supervisory integration is included.'},
  {id:'monitor',label:'Shared monitoring',description:'The integrated view receives this point and its quality. It has no request output for this point.'},
  {id:'control',label:'Shared monitoring + permitted request',description:'This example includes one named request through an explicitly configured interface. Other commands are not implied.'},
];
export function occIntegrationsFor(app){
  return app==='telecom'?[
    {id:'native',label:'No telecom SCADA link',description:'The native service retains its own diagnostics. No point or request is exchanged with telecom SCADA in this example.'},
    {id:'monitor',label:'Telecom SCADA monitoring',description:'Communications SCADA acquires the named device condition and quality. No telecom SCADA request output is included for this point.'},
    {id:'control',label:'Telecom SCADA monitoring + named request',description:'Communications SCADA also exposes the one named request through a configured interface. Other maintenance or service commands are not implied.'}
  ]:OCC_INTEGRATIONS;
}
export const OCC_CONDITIONS=[
  {id:'normal',label:'Fresh observation'},
  {id:'fault',label:'Different equipment condition'},
  {id:'link-loss',label:'Selected data path lost'},
  {id:'local',label:'Request not permitted'},
  {id:'feedback-missing',label:'Outcome feedback missing'},
];
const apps=new Map(OCC_APPLICATIONS.map(a=>[a.id,a])),points=new Map(OCC_DEVICE_POINTS.map(p=>[p.id,p]));
export function normalizeOccState(input={}){
  const app=apps.has(input.app)?input.app:'telecom';
  const point=apps.get(app).points.includes(input.point)?input.point:apps.get(app).points[0];
  const p=points.get(point);
  let integration=OCC_INTEGRATIONS.some(x=>x.id===input.integration)?input.integration:'monitor';
  if((!p.request||p.sharedRequest===false)&&integration==='control')integration='monitor';
  return{app,point,integration,acquisition:p.supportsNms&&input.acquisition==='nms'?'nms':'direct',condition:OCC_CONDITIONS.some(x=>x.id===input.condition)?input.condition:'normal',trace:input.trace==='request'?'request':'indication',step:Math.max(0,Math.min(4,Math.floor(Number(input.step)||0)))};
}
export function occStateFromQuery(app,point,query){return normalizeOccState({app,point,integration:query.get('occIntegration'),acquisition:query.get('occAcquisition'),condition:query.get('occCondition'),trace:query.get('occTrace'),step:query.get('occStep')});}
export function writeOccQuery(url,input){
  for(const key of ['occIntegration','occAcquisition','occCondition','occTrace','occStep'])url.searchParams.delete(key);
  if(!input)return;
  const s=normalizeOccState(input);
  for(const [key,value,initial]of [['occIntegration',s.integration,'monitor'],['occAcquisition',s.acquisition,'direct'],['occCondition',s.condition,'normal'],['occTrace',s.trace,'indication'],['occStep',s.step,0]])if(value!==initial)url.searchParams.set(key,String(value));
}
export function occContextFor(component,variant=''){
  const mapping={'telecom-scada':['telecom','pa-health'],'operations-signalling-workstation':['traffic','track-occupation'],'operations-traffic-supervision':['traffic','track-occupation'],'operations-power-control':['power','breaker-position'],'operations-power-supervision':['power','breaker-position'],'operations-station-supervision':['facilities','comfort-fan'],'occ-supervisory-request':['telecom','pa-health'],'occ-field-indication':['telecom','pa-health'],'occ-information-quality':['telecom','pa-health'],'occ-record-timeline':['telecom','pa-health'],'occ-alarm-queue':['telecom','pa-health'],'occ-cctv-assessment':['video','video-view'],'occ-passenger-communications':['passenger','pa-zone'],'occ-access-supervision':['security','access-door']};
  const found=mapping[component];if(found)return normalizeOccState({app:found[0],point:found[1],trace:component==='occ-supervisory-request'?'request':'indication'});
  const app={traffic:'traffic',power:'power',station:'facilities',telecom:'telecom'}[variant];
  return app?normalizeOccState({app}):null;
}

// Only cross-link responsibilities for which this inspector has a named example.
export function occExampleForDomain(domain){
  const routes={telecom:['telecom','pa-health'],traction:['power','breaker-position'],building:['facilities','comfort-fan'],tunnel:['facilities','tunnel-fan'],signalling:['traffic','track-occupation'],passenger:['passenger','pa-zone'],security:['video','video-view'],radio:['radio','radio-call'],network:['network','switch-link']};
  const route=routes[domain];return route?{app:route[0],point:route[1]}:null;
}

export function evaluateOccPoint(input={}){
  const state=normalizeOccState(input),point=points.get(state.point),application=apps.get(state.app);
  const lost=state.condition==='link-loss',missing=state.condition==='feedback-missing',denied=state.condition==='local';
  const shared=state.integration!=='native',requestDefined=!!point.request;
  const requestEnabled=requestDefined&&(state.integration==='control'||state.integration==='native'&&state.app!=='telecom');
  const observed=state.condition==='fault'?point.fault:point.normal;
  const quality=lost?'Stale · selected path unavailable':missing?'Unavailable · selected feedback missing':'Fresh illustrative observation';
  const acquisition=state.acquisition==='nms'?'Native equipment manager / NMS':point.acquisition;
  const supervisor=state.app==='telecom'?(shared?'Communications SCADA':'No telecom SCADA interface'):shared?`${point.native} → common HMI`:point.native;
  let steps;
  if(state.trace==='request')steps=[
    {label:'Choose the interface',actor:'supervision',text:!requestDefined?'This selected point is an indication. No command that changes its reported value is provided.':!requestEnabled?(state.app==='telecom'?(shared?'Telecom SCADA monitoring carries no request output. Select the explicitly configured request interface to compare that alternative.':'No telecom SCADA interface is included. Native service or maintenance functions are separate and are not exercised by this trace.'):'Shared monitoring carries no request output. Choose the native application or enable the named integrated request to compare that alternative.'):`${point.request} is available in this selected teaching configuration.`},
    {label:'Deliver the request',actor:'transport',text:!requestEnabled?'No command leaves this interface.':lost?'The selected transport path is unavailable; delivery is unconfirmed.':`The request uses the configured application interface to ${acquisition.toLowerCase()}. Service payload and management traffic retain their own paths.`},
    {label:'Endpoint decision',actor:'acquisition',text:!requestEnabled||lost?'No endpoint action is inferred.':denied?'The endpoint rejects this request under the selected permission/mode condition.':`The receiving ${point.native.toLowerCase()} or device interface checks the configured request. Acceptance is a separate observation from the final state.`},
    {label:'Returned evidence',actor:'field',text:!requestEnabled||lost||denied?'The trace does not infer a changed equipment condition.':missing?'The request may have been accepted, but the outcome feedback is unavailable.':point.evidence},
    {label:'Display and record',actor:'record',text:!requestEnabled?'No request record is claimed; monitoring remains available according to its own path.':lost?'Record an unconfirmed delivery, without inventing a current equipment state.':denied?'Display the rejection separately from continuing status information.':missing?'Display an unconfirmed outcome; keep acceptance and returned field evidence separate.':'Present the returned evidence with point identity, quality and time. This is an interface trace, not an operated device.'},
  ];else steps=[
    {label:'Device observation',actor:'field',text:`${point.asset}: ${point.source}. Selected source condition: ${observed.toLowerCase()}.`},
    {label:'Acquire the point',actor:'acquisition',text:`${acquisition} exposes the selected value and quality. ${state.acquisition==='nms'?'The manager may aggregate detail; its alarm meaning must remain defined.':'A direct device interface does not require an extra NMS hop.'}`},
    {label:'Transport the data',actor:'transport',text:lost?'The selected data path is lost. The last observation retains its age; a missing update is not a new normal value.':'The configured network transports this diagnostic or status exchange. Audio, video and other service payloads are separate exchanges.'},
    {label:'Present the point',actor:'supervision',text:state.app==='telecom'&&!shared?'No telecom SCADA point is presented in this configuration. The native service has its own diagnostics and availability dependencies.':lost?'Present a stale/unavailable point, while keeping device failure and path failure distinct.':missing?'The selected feedback is unavailable even though other communication may work.':`${supervisor} presents ${observed.toLowerCase()} with its source and quality.`},
    {label:'Retain its context',actor:'record',text:state.app==='telecom'&&!shared?'No telecom SCADA history record is claimed. Any native service records belong to that service and its configured storage.':lost||missing?'Retain the last known record and its quality. Do not relabel it as a fresh successful observation.':`Retain the point identity, observed state and applicable timestamps. Acknowledging an alarm does not repair ${point.asset}.`},
  ];
  return{state,point,application,shared,requestDefined,requestEnabled,acquisition,supervisor,quality,observed,steps,active:steps[state.step],displayValue:state.app==='telecom'&&!shared?'Not shared with telecom SCADA':lost?'Last known · not refreshed':missing?'Selected feedback unavailable':observed,requestStatus:state.app==='telecom'&&!shared?'No telecom SCADA request interface':!requestDefined?'Indication point only':!requestEnabled?'Monitoring-only integration':lost?'Delivery unconfirmed':denied?'Request rejected':missing?'Outcome unconfirmed':'Named request available'};
}
